import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: PortalContact","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: PortalContact"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/PortalContact"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/PortalContact"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/PortalContact.md","filePath":"api/@jsprismarine/prismarine/classes/PortalContact.md","lastUpdated":1794400648000}`),a={name:`api/@jsprismarine/prismarine/classes/PortalContact.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / PortalContact</p><h1 id="class-portalcontact" tabindex="-1">Class: PortalContact <a class="header-anchor" href="#class-portalcontact" aria-label="Permalink to “Class: PortalContact”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L51" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:51</a></p><p>One entity&#39;s running contact with a portal, as Java&#39;s <code>PortalProcessor</code> keeps it.</p><p>The world calls <a href="#touch">PortalContact.touch</a> on every tick the entity&#39;s box overlaps a portal block, and the entity calls <a href="#tick">PortalContact.tick</a> once per tick from its own update. The time inside climbs by one per touched tick and drops by four per tick outside, so a player who steps out and back in does not start over, and the entity drops the contact once <a href="#hasexpired">PortalContact.hasExpired</a> says the time has run back down to zero.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new PortalContact</strong>(<code>entryPosition</code>): <code>PortalContact</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L60" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:60</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entryposition" tabindex="-1">entryPosition <a class="header-anchor" href="#entryposition" aria-label="Permalink to “entryPosition”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the entity stood when it first touched the portal.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>PortalContact</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getentryposition" tabindex="-1">getEntryPosition() <a class="header-anchor" href="#getentryposition" aria-label="Permalink to “getEntryPosition()”">​</a></h3><blockquote><p><strong>getEntryPosition</strong>(): <a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L110" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:110</a></p><p>Where the entity most recently stood in the portal.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><hr><h3 id="getportal" tabindex="-1">getPortal() <a class="header-anchor" href="#getportal" aria-label="Permalink to “getPortal()”">​</a></h3><blockquote><p><strong>getPortal</strong>(): <code>PortalBlockRef</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L115" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:115</a></p><p>The portal block the entity most recently overlapped, or undefined when no touch named one.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>PortalBlockRef</code> | <code>undefined</code></p><hr><h3 id="getportaltime" tabindex="-1">getPortalTime() <a class="header-anchor" href="#getportaltime" aria-label="Permalink to “getPortalTime()”">​</a></h3><blockquote><p><strong>getPortalTime</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L105" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:105</a></p><p>Ticks accumulated inside the portal, after decay.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="hasexpired" tabindex="-1">hasExpired() <a class="header-anchor" href="#hasexpired" aria-label="Permalink to “hasExpired()”">​</a></h3><blockquote><p><strong>hasExpired</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L100" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:100</a></p><p>Whether the time inside has run back down to zero, so the contact can be dropped.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="tick" tabindex="-1">tick() <a class="header-anchor" href="#tick" aria-label="Permalink to “tick()”">​</a></h3><blockquote><p><strong>tick</strong>(<code>delayTicks</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L86" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:86</a></p><p>Advances the contact by one tick.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="delayticks" tabindex="-1">delayTicks <a class="header-anchor" href="#delayticks" aria-label="Permalink to “delayTicks”">​</a></h5><p><code>number</code></p><p>Ticks inside the portal before the trip starts, from <a href="./../#portal-transition-ticks">PORTAL_TRANSITION_TICKS</a>. Zero fires on the first tick.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>true</code> when the time inside has reached <code>delayTicks</code> this tick.</p><hr><h3 id="touch" tabindex="-1">touch() <a class="header-anchor" href="#touch" aria-label="Permalink to “touch()”">​</a></h3><blockquote><p><strong>touch</strong>(<code>entryPosition</code>, <code>portal?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/849f4836971fd51a4aff0267f9743928599655e4/packages/prismarine/src/entity/PortalContact.ts#L73" target="_blank" rel="noreferrer">prismarine/src/entity/PortalContact.ts:73</a></p><p>Records that the entity overlaps a portal block on the current tick.</p><p>Several touches in one tick count once. The position is kept so the trip can be resolved from where the entity stood, not from where it was when the contact began.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entryposition-1" tabindex="-1">entryPosition <a class="header-anchor" href="#entryposition-1" aria-label="Permalink to “entryPosition”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><h5 id="portal" tabindex="-1">portal? <a class="header-anchor" href="#portal" aria-label="Permalink to “portal?”">​</a></h5><p><code>PortalBlockRef</code></p><p>The portal block the entity overlaps, which the trip is resolved from once the timer runs out. A touch without one leaves the last known block in place.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,69)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};